package com.rpb.reservation.workforce.payroll.governance;
import static com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.*;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import com.rpb.reservation.workforce.payroll.*;
import java.time.*;import java.util.*;import java.math.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
/** Read-only assumptions use the real capture and calculator, never a second payroll formula. */
@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class PayChangeImpactService {
 private final PayChangeService changes;private final PayChangeRepository repository;private final PayChangeDrafts drafts;private final PayrollSources sources;private final PayrollCalculationService calculator;private final PayrollAccess access;private final PayrollRepository payroll;private final Clock clock;
 public PayChangeImpactService(PayChangeService changes,PayChangeRepository repository,PayChangeDrafts drafts,PayrollSources sources,PayrollCalculationService calculator,PayrollAccess access,PayrollRepository payroll,Clock clock){this.changes=changes;this.repository=repository;this.drafts=drafts;this.sources=sources;this.calculator=calculator;this.access=access;this.payroll=payroll;this.clock=clock;}
 public Impact preview(CurrentActor actor,UUID store,UUID id,String value){var r=changes.detail(actor,store,id);var month=PayrollProfileValidation.month(value);var c=r.content();var issues=new LinkedHashSet<String>();var warnings=new ArrayList<String>();if(r.effectiveDate().isBefore(LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")))))warnings.add("RETROACTIVE_EFFECTIVE_DATE");String standard=standard(c.beforeProfile()==null?c.adoption()==null?null:c.adoption().rule():c.beforeProfile().rule(),c.profile()==null?c.derivedRule():c.profile().rule());if(standard!=null&&new BigDecimal(standard).signum()<0)warnings.add("PAY_REDUCTION");if(c.patch().stream().anyMatch(d->d.path().contains("items")&&d.after()!=null&&d.after().contains("deduction")))warnings.add("DEDUCTION_REVIEW");
  if(PayChangeRiskHints.newDeduction(c))warnings.add("NEW_DEDUCTION");
  try{if(!c.baselineHash().equals(drafts.baselineHash(actor,r.companyId(),r.employeeId(),c)))issues.add("SOURCE_BASELINE_CHANGED");}catch(com.rpb.reservation.workforce.domain.WorkforceException e){if(e.status()==403)throw e;issues.add("SOURCE_BASELINE_CHANGED");issues.add(e.code());}if(r.employeeId()==null){issues.add("TEMPLATE_CANDIDATE_ONLY");return result(r,value,standard,null,null,issues,warnings,null,null);}
  access.enter(actor,store,r.companyId());if(!issues.isEmpty())return result(r,value,standard,null,null,issues,warnings,null,null);
  if(c.supplemental()!=null&&!c.supplemental().isEmpty()){var gross=c.supplemental().stream().filter(p->p.settlementMonth().equals(value)).flatMap(p->p.items().stream()).map(i->new BigDecimal(i.amount())).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2).toPlainString();issues.add("SUPPLEMENTAL_CALCULATION_REQUIRED");return result(r,value,gross,null,null,issues,warnings,null,null);}
  var inputs=new ArrayList<LineInput>();payroll.forMonth(actor.tenantId(),r.companyId(),month).ifPresent(b->inputs.addAll(payroll.inputs(actor.tenantId(),b.id())));inputs.removeIf(i->i.employeeId().equals(r.employeeId()));inputs.add(repository.monthlyBaseline(actor.tenantId(),r.companyId(),r.employeeId(),month));
  var before=sources.capture(actor.tenantId(),r.companyId(),month,inputs);access.enter(actor,store,r.companyId(),before.stores());var overrides=new HashMap<UUID,LineInput>();for(var m:c.months())if(m.month().equals(value))overrides.put(r.employeeId(),m.after());
  var after=sources.captureAssuming(actor.tenantId(),r.companyId(),month,inputs,new PayrollSources.Assumptions(r.id(),r.revision(),r.hash(),c.profile()==null?List.of():List.of(c.profile()),Map.copyOf(overrides)));access.enter(actor,store,r.companyId(),after.stores());var old=calculator.calculate(before,month).lines().stream().filter(l->l.employeeId().equals(r.employeeId())).findFirst().orElse(null);var next=calculator.calculate(after,month).lines().stream().filter(l->l.employeeId().equals(r.employeeId())).findFirst().orElse(null);
  boolean future=month.isAfter(YearMonth.now(clock.withZone(ZoneId.of("Asia/Singapore"))));boolean oldUnknown=future&&variable(old),nextUnknown=future&&variable(next);if(oldUnknown||nextUnknown)issues.add("FUTURE_ATTENDANCE_SOURCES_INCOMPLETE");if(future&&(!oldUnknown&&old!=null||!nextUnknown&&next!=null))warnings.add("FIXED_FUTURE_CONTRACT_ASSUMPTION");if(old==null||next==null)issues.add("EMPLOYEE_NOT_IN_MONTH");if(old!=null)issues.addAll(old.issues());if(next!=null)issues.addAll(next.issues());warnings.add("ESTIMATE_USING_CURRENT_SOURCES");return result(r,value,standard,old!=null&&!oldUnknown&&old.issues().isEmpty()?old.netPay():null,next!=null&&!nextUnknown&&next.issues().isEmpty()?next.netPay():null,issues,warnings,before.fingerprint(),after.fingerprint());
 }
 private boolean variable(PayrollLine line){return line==null||line.profile()==null||!PayrollGeneration.fixed(line.profile().rule());}
 private Impact result(Request r,String month,String standard,String before,String after,Set<String> issues,List<String> warnings,String beforeFp,String afterFp){var c=r.content();var oldRule=c.beforeProfile()==null?c.adoption()==null?null:c.adoption().rule():c.beforeProfile().rule();var newRule=c.profile()==null?c.derivedRule():c.profile().rule();String oldStandard=oldRule!=null&&oldRule.basis().equals("monthly")?fixed(oldRule).setScale(2).toPlainString():null,newStandard=newRule!=null&&newRule.basis().equals("monthly")?fixed(newRule).setScale(2).toPlainString():null;String percent=standard==null||oldStandard==null||new BigDecimal(oldStandard).signum()==0?null:new BigDecimal(standard).multiply(BigDecimal.valueOf(100)).divide(new BigDecimal(oldStandard).abs(),2,RoundingMode.HALF_UP).toPlainString();return new Impact(r.id(),r.revision(),r.hash(),month,standard,before,after,before==null||after==null?null:new BigDecimal(after).subtract(new BigDecimal(before)).setScale(2).toPlainString(),List.copyOf(issues),List.copyOf(warnings),beforeFp,afterFp,clock.instant(),oldStandard,newStandard,percent);}
 private String standard(Rule before,Rule after){if(before==null||after==null||!before.basis().equals("monthly")||!after.basis().equals("monthly"))return null;return fixed(after).subtract(fixed(before)).setScale(2).toPlainString();}
 private BigDecimal fixed(Rule rule){var value=new BigDecimal(rule.rate());for(var i:rule.items())if(!"payable".equals(i.proration())&&!i.kind().equals("employer_charge"))value=value.add(new BigDecimal(i.amount()).multiply(PayItemKinds.DEDUCTIONS.contains(i.kind())?BigDecimal.ONE.negate():BigDecimal.ONE));return value;}
}
